mapper.select:
select u.user_id, u.organization_id, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.sn_userid, u.create_by, u.create_time, u.remark, u.theme, u.font, u.language, org.py_label, org.py_name, d.dept_name, d.leader, r.role_id, r.role_name, r.role_key, r.role_sort, r.data_scope, r.status as role_status from sys_user u left join sys_organization org on u.organization_id::text = org.organization_id::text left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND to_char(u.create_time::timestamp, 'YYMMDD') >= to_char(#{params.beginTime}::timestamp, 'YYMMDD')
AND to_char(u.create_time::timestamp, 'YYMMDD') <= to_char(#{params.endTime}::timestamp, 'YYMMDD')
AND u.organization_id::text = cast(#{organizationId} as text)
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE (',' || coalesce(t.ancestors, '') || ',') LIKE ('%,' || cast(#{deptId} as text) || ',%') ))
${params.dataScope}

select distinct u.user_id, u.organization_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.avatar, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id where u.del_flag = '0'
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE (',' || coalesce(t.ancestors, '') || ',') LIKE ('%,' || cast(#{deptId} as text) || ',%') ))
${params.dataScope}

select distinct u.user_id, u.organization_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.avatar, u.create_time, u.theme, u.font, u.language from sys_user u left join sys_organization org on u.organization_id::text = org.organization_id::text left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

mapper.update:
update sys_user
organization_id = #{organizationId}, dept_id = #{deptId}, user_name = #{userName}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, theme = #{theme}, font = #{font}, language = #{language}, sn_userid = #{snUserid}, update_time = now()
where user_id = #{userId}

mapper.select:
select distinct u.user_id, u.organization_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber,
       u.status, u.sn_userid, u.avatar, u.create_time,
       d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader, d.status as dept_status,
       r.role_id, r.role_name, r.role_key, r.role_sort, r.data_scope, r.status as role_status
from sys_user u
left join sys_dept d on u.dept_id = d.dept_id
left join sys_user_role ur on u.user_id = ur.user_id
left join sys_role r on r.role_id = ur.role_id and r.del_flag = '0'
where u.del_flag = '0'

    AND u.status = #{status}


    AND u.user_id = #{userId}


    AND u.user_id = #{scopeUserId}


    AND u.sn_userid = #{snUserid}


    AND u.sn_userid IS NOT NULL AND TRIM(u.sn_userid) <> ''


    AND u.organization_id::text = #{orgId}


    AND (u.dept_id = #{deptId} OR u.dept_id IN (
        SELECT t.dept_id FROM sys_dept t
        WHERE (',' || coalesce(t.ancestors, '') || ',') LIKE ('%,' || cast(#{deptId} as text) || ',%')
    ))


    AND u.dept_id = #{scopeDeptId}


    AND (u.dept_id = #{scopeDeptId} OR u.dept_id IN (
        SELECT t.dept_id FROM sys_dept t
        WHERE (',' || coalesce(t.ancestors, '') || ',') LIKE ('%,' || cast(#{scopeDeptId} as text) || ',%')
    ))


    AND (
        u.nick_name ILIKE concat('%', #{keyword}, '%')
        OR u.user_name ILIKE concat('%', #{keyword}, '%')
        OR u.sn_userid ILIKE concat('%', #{keyword}, '%')
    )


    AND EXISTS (
        SELECT 1 FROM sys_user_role ur2
        INNER JOIN sys_role r2 ON r2.role_id = ur2.role_id AND r2.del_flag = '0'
        WHERE ur2.user_id = u.user_id
          AND r2.role_key IN
        
            #{rk}
        
    )

${params.dataScope}
order by u.nick_name, u.user_id
